import{_ as r,C as n,o as i,c,j as t,a as o,b as d,w as a,E as l,ao as p,an as h}from"./chunks/framework.C1Zpw0WN.js";const C=JSON.parse('{"title":"Operators","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/operators.md","filePath":"concepts/operators.md","lastUpdated":null}'),u={name:"concepts/operators.md"};function g(m,e,y,f,b,v){const s=n("Mermaid");return i(),c("div",null,[e[1]||(e[1]=t("h1",{id:"Operator-concepts",tabindex:"-1"},[o("Operators "),t("a",{class:"header-anchor",href:"#Operator-concepts","aria-label":'Permalink to "Operators {#Operator-concepts}"'},"​")],-1)),e[2]||(e[2]=t("p",null,[o("Every physics process in AtmosTransport is implemented behind an "),t("strong",null,"abstract operator type"),o(" with a "),t("code",null,"No<Operator>"),o(" no-op default. The runtime composes operators through a fixed Strang palindrome; users swap implementations by changing one field in the TOML config (or by implementing a new subtype and registering it).")],-1)),e[3]||(e[3]=t("h2",{id:"The-five-operator-families",tabindex:"-1"},[o("The five operator families "),t("a",{class:"header-anchor",href:"#The-five-operator-families","aria-label":'Permalink to "The five operator families {#The-five-operator-families}"'},"​")],-1)),(i(),d(p,null,{default:a(()=>[l(s,{id:"mermaid-9",class:"mermaid-diagram",graph:"classDiagram%0A%20%20%20%20class%20AbstractOperator%0A%20%20%20%20class%20AbstractAdvectionScheme%0A%20%20%20%20class%20AbstractDiffusion%0A%20%20%20%20class%20AbstractConvection%0A%20%20%20%20class%20AbstractSurfaceFluxOperator%0A%20%20%20%20class%20AbstractChemistryOperator%0A%20%20%20%20class%20UpwindScheme%0A%20%20%20%20class%20SlopesScheme%0A%20%20%20%20class%20PPMScheme%0A%20%20%20%20class%20LinRoodPPMScheme%0A%20%20%20%20class%20NoDiffusion%0A%20%20%20%20class%20ImplicitVerticalDiffusion%0A%20%20%20%20class%20NoConvection%0A%20%20%20%20class%20CMFMCConvection%0A%20%20%20%20class%20TM5Convection%0A%20%20%20%20class%20NoSurfaceFlux%0A%20%20%20%20class%20SurfaceFluxOperator%0A%20%20%20%20class%20NoChemistry%0A%20%20%20%20class%20ExponentialDecay%0A%20%20%20%20class%20CompositeChemistry%0A%0A%20%20%20%20AbstractOperator%20%3C%7C--%20AbstractAdvectionScheme%0A%20%20%20%20AbstractOperator%20%3C%7C--%20AbstractDiffusion%0A%20%20%20%20AbstractOperator%20%3C%7C--%20AbstractConvection%0A%20%20%20%20AbstractOperator%20%3C%7C--%20AbstractSurfaceFluxOperator%0A%20%20%20%20AbstractOperator%20%3C%7C--%20AbstractChemistryOperator%0A%20%20%20%20AbstractAdvectionScheme%20%3C%7C--%20UpwindScheme%0A%20%20%20%20AbstractAdvectionScheme%20%3C%7C--%20SlopesScheme%0A%20%20%20%20AbstractAdvectionScheme%20%3C%7C--%20PPMScheme%0A%20%20%20%20AbstractAdvectionScheme%20%3C%7C--%20LinRoodPPMScheme%0A%20%20%20%20AbstractDiffusion%20%3C%7C--%20NoDiffusion%0A%20%20%20%20AbstractDiffusion%20%3C%7C--%20ImplicitVerticalDiffusion%0A%20%20%20%20AbstractConvection%20%3C%7C--%20NoConvection%0A%20%20%20%20AbstractConvection%20%3C%7C--%20CMFMCConvection%0A%20%20%20%20AbstractConvection%20%3C%7C--%20TM5Convection%0A%20%20%20%20AbstractSurfaceFluxOperator%20%3C%7C--%20NoSurfaceFlux%0A%20%20%20%20AbstractSurfaceFluxOperator%20%3C%7C--%20SurfaceFluxOperator%0A%20%20%20%20AbstractChemistryOperator%20%3C%7C--%20NoChemistry%0A%20%20%20%20AbstractChemistryOperator%20%3C%7C--%20ExponentialDecay%0A%20%20%20%20AbstractChemistryOperator%20%3C%7C--%20CompositeChemistry%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=h(`<h2 id="The-apply!-contract" tabindex="-1">The <code>apply!</code> contract <a class="header-anchor" href="#The-apply!-contract" aria-label="Permalink to &quot;The \`apply!\` contract {#The-apply!-contract}&quot;">​</a></h2><p>Each operator family&#39;s mutating entry point has a uniform shape, with the second positional argument carrying whatever time-resolved data that family needs:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Family</th><th style="text-align:right;">Signature</th></tr></thead><tbody><tr><td style="text-align:right;">Advection</td><td style="text-align:right;"><code>apply!(state, fluxes, grid, scheme, dt; workspace, cfl_limit, diffusion_op, emissions_op, meteo)</code></td></tr><tr><td style="text-align:right;">Diffusion</td><td style="text-align:right;"><code>apply!(state, meteo, grid, op::AbstractDiffusion, dt; workspace)</code></td></tr><tr><td style="text-align:right;">Convection</td><td style="text-align:right;"><code>apply!(state, forcing::ConvectionForcing, grid, op::AbstractConvection, dt; workspace)</code></td></tr><tr><td style="text-align:right;">Surface flux</td><td style="text-align:right;"><code>apply!(state, meteo, grid, op::AbstractSurfaceFluxOperator, dt; workspace = nothing)</code></td></tr><tr><td style="text-align:right;">Chemistry</td><td style="text-align:right;"><code>apply!(state, meteo, grid, op::AbstractChemistryOperator, dt; workspace = nothing)</code></td></tr></tbody></table><p>Every method mutates <code>state</code> in place. Performance-sensitive implementations keep reusable scratch buffers in workspaces. Each family provides an identity operator (<code>NoAdvection</code>, <code>NoDiffusion</code>, <code>NoConvection</code>, <code>NoSurfaceFlux</code>, or <code>NoChemistry</code>) so the runtime can compose one typed model without conditionally calling absent physics.</p><p>Topology dispatch happens <strong>inside</strong> each <code>apply!</code> method, not on a separate axis: an LL state and a CS state route through different specialized kernels via Julia&#39;s multiple dispatch on the grid type.</p><h2 id="Advection" tabindex="-1">Advection <a class="header-anchor" href="#Advection" aria-label="Permalink to &quot;Advection {#Advection}&quot;">​</a></h2><p><code>AbstractAdvectionScheme</code> is the root; the concrete schemes live in <code>src/Operators/Advection/schemes.jl</code>:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Subtype</th><th style="text-align:right;">Order</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;"><code>UpwindScheme</code></td><td style="text-align:right;">1</td><td style="text-align:right;">Donor-cell; cheap, very diffusive.</td></tr><tr><td style="text-align:right;"><code>SlopesScheme{L}</code></td><td style="text-align:right;">2</td><td style="text-align:right;">Russell-Lerner slopes (TM5 <code>sl_advection</code> port). Limiter parameter <code>L</code>.</td></tr><tr><td style="text-align:right;"><code>PPMScheme{L}</code></td><td style="text-align:right;">3 in smooth regions</td><td style="text-align:right;">Putman-Lin Piecewise Parabolic. Limiter parameter <code>L</code>. Supported on LL and CS split-sweep; RG supports upwind only.</td></tr><tr><td style="text-align:right;"><code>LinRoodPPMScheme</code></td><td style="text-align:right;">5 or 7</td><td style="text-align:right;">FV3 Lin-Rood PPM with cross-term advection (CS only); ORD=7 adds a panel-boundary correction. Selectable <code>ppm_order ∈ {5, 7}</code>.</td></tr></tbody></table><p>Limiter parameter <code>L</code> ranges over <code>NoLimiter</code>, <code>MonotoneLimiter</code>, <code>PositivityLimiter</code> — declared in the same file. <code>PPMScheme()</code> defaults to <code>MonotoneLimiter()</code>. The default limiter is signed and constant-offset equivariant; only <code>PositivityLimiter</code> uses tracer zero as a bound.</p><p><strong>TOML config</strong> (preferred form):</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">advection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scheme = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;slopes&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # &quot;upwind&quot; | &quot;slopes&quot; | &quot;ppm&quot; | &quot;linrood&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Cubed-sphere only: pick the LinRoodPPM order (5 or 7).</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Only valid with scheme = &quot;linrood&quot;; setting ppm_order with</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># scheme = &quot;ppm&quot; errors at config-parse time.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># scheme    = &quot;linrood&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ppm_order = 7</span></span></code></pre></div><p>A <code>NoAdvection</code> identity operator is available for isolating other operators (e.g. convection-only timing, regression). Select with <code>[advection] scheme = &quot;none&quot;</code>. Diffusion-only runs are supported as a single mass-conserving vertical solve. Surface fluxes require an advection palindrome and are therefore rejected with <code>NoAdvection</code>.</p><h2 id="Diffusion" tabindex="-1">Diffusion <a class="header-anchor" href="#Diffusion" aria-label="Permalink to &quot;Diffusion {#Diffusion}&quot;">​</a></h2><p><code>AbstractDiffusion</code> is the root; concrete subtypes:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Subtype</th><th style="text-align:right;">Use</th></tr></thead><tbody><tr><td style="text-align:right;"><code>NoDiffusion()</code></td><td style="text-align:right;">Identity no-op; default when <code>[diffusion]</code> is absent or <code>kind = &quot;none&quot;</code>.</td></tr><tr><td style="text-align:right;"><code>ImplicitVerticalDiffusion{FT, KzF, SFC}</code></td><td style="text-align:right;">Backward-Euler vertical diffusion driven by an <code>AbstractTimeVaryingField</code> Kz. <code>SFC</code> chooses midpoint source splitting or source-before-full-solve ordering.</td></tr></tbody></table><p>The implicit solver runs a per-column Thomas tridiagonal solve; the column kernel is exposed as <code>solve_tridiagonal!</code> for tests and adjoint variants. The <code>(a, b, c)</code> tridiagonal coefficients are kept as named locals (rather than fused into a pre-factored form) so a future adjoint kernel can transpose them mechanically.</p><p><strong>TOML config</strong> (<code>[diffusion]</code> block):</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">diffusion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind  = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;constant&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">value = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Kz [m²/s]; broadcast to all (i, j, k)</span></span></code></pre></div><p><code>kind = &quot;none&quot;</code> (or omitting the block entirely) selects <code>NoDiffusion</code>. Cubed-sphere binaries carrying PBL surface sections can use <code>kind = &quot;tm5_beljaars_viterbo_local_kz&quot;</code>. On lat-lon and cubed-sphere grids, <code>surface_flux_boundary = true</code> adds configured surface mass before one full implicit vertical solve (<code>S(dt) -&gt; V(dt)</code>) instead of using the separate midpoint split (<code>V(dt/2) -&gt; S(dt) -&gt; V(dt/2)</code>). The key name is historical: this changes operator ordering, not the lower row of the tridiagonal system. Reduced-Gaussian transport currently supports midpoint splitting only and rejects <code>surface_flux_boundary = true</code> while building the runtime recipe. Profile / derived / precomputed Kz fields exist in <code>src/State/Fields/</code> — see <a href="/AtmosTransport.jl/stable/concepts/state_and_basis#State-and-basis">State &amp; basis</a> for the full field-type list.</p><h2 id="Convection" tabindex="-1">Convection <a class="header-anchor" href="#Convection" aria-label="Permalink to &quot;Convection {#Convection}&quot;">​</a></h2><p><code>AbstractConvection</code> is the root; concrete subtypes:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Subtype</th><th style="text-align:right;">Forcing carrier</th><th style="text-align:right;">Source</th></tr></thead><tbody><tr><td style="text-align:right;"><code>NoConvection()</code></td><td style="text-align:right;">—</td><td style="text-align:right;">Identity no-op; default.</td></tr><tr><td style="text-align:right;"><code>CMFMCConvection()</code></td><td style="text-align:right;"><code>ConvectionForcing.{cmfmc, dtrain}</code></td><td style="text-align:right;">GCHP-style upwind moist convection; mass flux + optional detrainment.</td></tr><tr><td style="text-align:right;"><code>TM5Convection{FT}()</code></td><td style="text-align:right;"><code>ConvectionForcing.tm5_fields.{entu, detu, entd, detd}</code></td><td style="text-align:right;">TM5 Tiedtke-1989 four-field entrainment / detrainment with an implicit column solve. Parametric on <code>FT</code>.</td></tr></tbody></table><p>Both real subtypes consume a <code>ConvectionForcing</code> carrier (declared in <code>src/MetDrivers/ConvectionForcing.jl</code>) — different physics, identical plumbing. <code>_refresh_forcing!</code> populates <code>model.convection_forcing</code> each substep by copying from the current met window; the operator does not call <code>current_time</code> itself.</p><p><strong>TOML config</strong> (<code>[convection]</code> block):</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">convection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cmfmc&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # or &quot;tm5&quot; / &quot;none&quot;</span></span></code></pre></div><p>The runtime picks <code>:cmfmc</code> only against binaries whose header carries the <code>:cmfmc</code> payload section (and <code>:dtrain</code> if requested); similarly for <code>:tm5</code> requiring <code>:entu / :detu / :entd / :detd</code>. Asking for a convection scheme the binary does not support is a <strong>load-time error</strong>, not a silent fallback.</p><h2 id="Surface-flux-sources" tabindex="-1">Surface flux (sources) <a class="header-anchor" href="#Surface-flux-sources" aria-label="Permalink to &quot;Surface flux (sources) {#Surface-flux-sources}&quot;">​</a></h2><p><code>AbstractSurfaceFluxOperator</code> is the root; concrete subtypes:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Subtype</th><th style="text-align:right;">Use</th></tr></thead><tbody><tr><td style="text-align:right;"><code>NoSurfaceFlux()</code></td><td style="text-align:right;">Identity no-op; default.</td></tr><tr><td style="text-align:right;"><code>SurfaceFluxOperator{M}</code></td><td style="text-align:right;">Applies a <code>PerTracerFluxMap</code> of <code>SurfaceFluxSource</code>s to the bottom-most layer (<code>k = Nz</code>).</td></tr></tbody></table><p><code>SurfaceFluxOperator</code> is materialized from <code>[tracers.&lt;name&gt;.surface_flux]</code> blocks and is the path for emissions inventories (EDGAR, GFED, GridFED, LMDz, …). See the worked CATRINE configs (<code>config/runs/catrine_*.toml</code>) for examples.</p><h2 id="Chemistry" tabindex="-1">Chemistry <a class="header-anchor" href="#Chemistry" aria-label="Permalink to &quot;Chemistry {#Chemistry}&quot;">​</a></h2><p><code>AbstractChemistryOperator</code> is the root; concrete subtypes:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Subtype</th><th style="text-align:right;">Use</th></tr></thead><tbody><tr><td style="text-align:right;"><code>NoChemistry()</code></td><td style="text-align:right;">Identity no-op; default.</td></tr><tr><td style="text-align:right;"><code>ExponentialDecay</code></td><td style="text-align:right;">Applies configured first-order loss rates to selected tracers.</td></tr><tr><td style="text-align:right;"><code>CompositeChemistry</code></td><td style="text-align:right;">Applies a typed tuple of chemistry operators in sequence.</td></tr></tbody></table><p>Chemistry runs after the transport and convection blocks. The same operator interface covers <code>CellState</code> and <code>CubedSphereState</code>; topology dispatch selects the storage-specific kernel launch.</p><h2 id="Transport-composition" tabindex="-1">Transport composition <a class="header-anchor" href="#Transport-composition" aria-label="Permalink to &quot;Transport composition {#Transport-composition}&quot;">​</a></h2><p>The directional advection shell is a palindrome. Its center follows the diffusion operator&#39;s surface-coupling policy:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>forward:   X → Y → Z   (each direction CFL-subcycled)</span></span>
<span class="line"><span>center A:  V(dt/2) → S(dt) → V(dt/2)   (default symmetric Strang split)</span></span>
<span class="line"><span>center B:  S(dt) → V(dt)               (LL/CS source-before-full-solve policy)</span></span>
<span class="line"><span>           [without surface flux, the center is one V(dt); NoDiffusion is a no-op]</span></span>
<span class="line"><span>reverse:   Z → Y → X   (same subcycle counts)</span></span>
<span class="line"><span>post:      apply!(convection)   (convection is outside the palindrome)</span></span>
<span class="line"><span>           apply!(chemistry)    (chemistry is outside the palindrome)</span></span></code></pre></div><p><code>V</code> is <code>apply_vertical_diffusion_vmr!</code> and <code>S</code> is <code>apply_surface_flux!</code>. Center A is time-symmetric and lets fresh bottom-layer storage diffuse in both half solves. Center B reproduces the supported GCHP-style placement of fresh surface storage before one full solve; it is an ordering policy, not a time-symmetric Strang center or a different tridiagonal boundary condition. Reduced-Gaussian transport implements Center A only.</p><p>Convection and chemistry sit <strong>outside</strong> the palindrome for the same reason: they are not commutative with advection at the per-substep level, and their natural cadence is the met window rather than the advection sub-step.</p><h2 id="Adding-a-new-operator" tabindex="-1">Adding a new operator <a class="header-anchor" href="#Adding-a-new-operator" aria-label="Permalink to &quot;Adding a new operator {#Adding-a-new-operator}&quot;">​</a></h2><p>The same recipe applies in every family:</p><ol><li><p>Subtype the abstract root: <code>struct MyConvection &lt;: AbstractConvection; … end</code>.</p></li><li><p>Provide a <code>No&lt;Operator&gt;</code> peer if one doesn&#39;t already cover your slot — usually it does.</p></li><li><p>Implement <code>apply!(state, …, op::MyConvection, dt; workspace)</code> for whichever grid types you support. Multiple dispatch on the grid type handles topology specialization.</p></li><li><p>Wire selection from TOML through <code>RuntimePhysicsSpecs.jl</code> and its topology-dispatched <code>materialize</code> methods.</p></li><li><p>Test that the <code>No&lt;Operator&gt;</code> path is bit-exact to the explicit no-op — this is the contract that lets future code skip the slot for free.</p></li></ol><h2 id="What&#39;s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#What&#39;s-next" aria-label="Permalink to &quot;What&amp;#39;s next {#What&#39;s-next}&quot;">​</a></h2><ul><li><a href="/AtmosTransport.jl/stable/concepts/binary_format#Binary-format">Binary format</a> — what the operator&#39;s input data looks like on disk, and how the runtime validates it.</li></ul>`,44))])}const A=r(u,[["render",g]]);export{C as __pageData,A as default};
